-- onboarding wizard (docs/superpowers/specs/2026-11-10-onboarding-wizard-design.md): profiles gain goals, target_roles and
-- target_companies, and onboarding_step grows from three steps to seven and now starts at 'goals'.
-- Generated by drizzle-kit; hand edits: this header, onboarding_rank, the statement order and the comment below.
-- Expand-only: three NOT NULL DEFAULT '{}' columns (a metadata-only add on Postgres 11+), two new checks on empty arrays,
-- and onboarding_step_ck dropped and re-added with the wider list, NOT VALID as 0006 first added it (validating would
-- scan every row, and rows older than 0006 were never checked). New and updated rows are checked either way.
-- Old rows keep their meaning: resume, confirm-facts and done keep their relative order under the new ranks.
ALTER TABLE "profiles" ADD COLUMN "goals" text[] DEFAULT '{}'::text[] NOT NULL;--> statement-breakpoint
ALTER TABLE "profiles" ADD COLUMN "target_roles" text[] DEFAULT '{}'::text[] NOT NULL;--> statement-breakpoint
ALTER TABLE "profiles" ADD COLUMN "target_companies" text[] DEFAULT '{}'::text[] NOT NULL;--> statement-breakpoint
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_goals_ck" CHECK (goals <@ ARRAY['find','build','interview','look']::text[] AND cardinality(goals) <= 4 AND (NOT 'look' = ANY(goals) OR cardinality(goals) = 1));--> statement-breakpoint
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_targets_ck" CHECK (cardinality(target_roles) <= 5 AND cardinality(target_companies) <= 10);--> statement-breakpoint

-- onboarding_rank (replaces 0007's three-step version): the order of the onboarding steps, goals 0 through done 6.
-- profiles_guard (0007) uses it to keep onboarding forward-only: a write to an earlier step is silently turned back into
-- the current one. 0007 is applied and immutable, so the rule is stated here; the function body is all that changes.
-- CREATE OR REPLACE keeps the PUBLIC EXECUTE grant from 0007.
CREATE OR REPLACE FUNCTION onboarding_rank(s text) RETURNS int
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
SELECT CASE s WHEN 'goals' THEN 0 WHEN 'target' THEN 1 WHEN 'resume' THEN 2 WHEN 'confirm-facts' THEN 3
  WHEN 'rules' THEN 4 WHEN 'template' THEN 5 WHEN 'done' THEN 6 END
$$;--> statement-breakpoint

ALTER TABLE "profiles" DROP CONSTRAINT "profiles_onboarding_step_ck";--> statement-breakpoint
ALTER TABLE "profiles" ADD CONSTRAINT "profiles_onboarding_step_ck" CHECK (onboarding_step IN ('goals','target','resume','confirm-facts','rules','template','done')) NOT VALID;--> statement-breakpoint
ALTER TABLE "profiles" ALTER COLUMN "onboarding_step" SET DEFAULT 'goals';
